```python
import math

class Shape():
    def __init__(self, shape_name: str):
        self.name = shape_name

    def get_name(self) -> str:
        return self.name

    def area(self) -> float:
        """Calculate the area（面积）。"""
        raise NotImplementedError

    def perimeter(self) -> float:
        """Calculate the perimeter(周长)."""
        raise NotImplementedError

class Circle(Shape):
    def __init__(self, circle_radius: float, circle_name: str):
        self.name = circle_name
        self.radius = circle_radius

    def perimeter(self) -> float:
        return 2 * math.pi * self.radius

    def area(self) -> float:
        return math.pi * (self.radius ** 2)

class Square(Shape):
    def __init__(self, square_side: float, square_name: str):
        self.name = square_name
        self.side = square_side

    def perimeter(self) -> float:
        return 4 * self.side

    def area(self) -> float:
        return self.side * self.side

# 直接实例化并调用
s = Shape("generic")
s.area()
```

