```python
1.  S <- new empty stack

2.  while ( there are unread input symbols ) {
3.      c <- next unread symbol

4.      if ( c is a left grouping symbol ) {
5.          push c onto S
6.      }

7.      else if ( c is right grouping symbol ) {
8.          if ( S is empty ) report Error and Stop
9.          d <- pop S
10.         if ( c and d do not match ) report Error and Stop
11.     }

12.     else {  // c is not a grouping symbol
