```python
class EmptyStackError(Exception):
    """Exception raised when pop is called on an empty stack."""

    def __str__(self) -> str:
        return "You called pop on an empty stack."

class Stack:
    def __init__(self):
        self._data = []
    def push(self, item):
        self._data.append(item)
    def pop(self):
        if not self._data:
            raise EmptyStackError()
        return self._data.pop()

s = Stack()
try:
    s.push(1)
    print('Popped:', s.pop())  # 有元素，正常弹出
    s.pop()  # 现在栈为空，会抛出
except EmptyStackError as e:
    print('Handled:', e)
```

