class _Node:
    def __init__(self, item):
        self.item = item
        self.next = None

class SimpleQueue:
    def __init__(self):
        self.head = None
        self.tail = None

    def enqueue(self, item):
        node = _Node(item)
        if not self.head:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node

    def dequeue(self):
        if not self.head:
            return None
        v = self.head.item
        self.head = self.head.next
        if not self.head:
            self.tail = None
        return v
```

