将值 3, 2, 1, 5 依次插入空 BST（使用迭代 insert）；然后对 BST 做中序遍历，打印结果是什么？（请读代码并判断输出）

```python
# 迭代插入示例（基于片段中的 Loop 版思路）
class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

def insert(root, value):
    if root is None:
        return Node(value)
    current = root
    while True:
        if value < current.key:
            if current.left is None:
                current.left = Node(value)
                break
            else:
                current = current.left
        else:
            if current.right is None:
                current.right = Node(value)
                break
            else:
                current = current.right
    return root

def inorder(node):
    if node is None:
        return []
    return inorder(node.left) + [node.key] + inorder(node.right)

root = None
for v in [3, 2, 1, 5]:
    root = insert(root, v)

print(' '.join(map(str, inorder(root))))
```

