def rovarspraket(word: str) -> str:
    vowels = 'aeiou'
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = ''

    for char in word:
        if char in vowels:
            result = result + char
        else:
            closest = vowels[0]
            for vowel in vowels:
                if abs(alphabet.index(vowel) - alphabet.index(char)) < abs(
                    alphabet.index(closest) - alphabet.index(char)
                ):
